public static class RedisKeyExtensions
{
    public static string AsAttemptKey(this string attemptId, string tenant)
        => $"attempt:{tenant}:{attemptId}";
}

var key = attemptId.AsAttemptKey("acme");
// identical IL: RedisKeyExtensions.AsAttemptKey(attemptId, "acme");

public static class RedisKeys
{
    extension(string attemptId)
    {
        public string AttemptCacheKey => $"attempt:{attemptId}";
        public bool LooksLikeAttemptId => attemptId.StartsWith("att_", StringComparison.Ordinal);
    }

    extension(string)
    {
        public static string SessionPrefix => "sess:";
    }
}

var id = "att_9f";
Console.WriteLine(id.AttemptCacheKey);
Console.WriteLine(string.SessionPrefix);

public static class PointExtensions
{
    public static void Translate(this ref Point p, int dx, int dy)
    {
        p.X += dx;
        p.Y += dy;
    }
}

var pt = new Point(0, 0);
pt.Translate(3, 4); // mutates pt because receiver is ref
